# Let's try to find a valid partition using backtracking with MRV heuristic
def find_week_backtrack():
    # State: groups (list of lists), and for each golfer, which groups they can join
    groups = [[] for _ in range(G)]

    # For each golfer, which groups are valid
    def get_valid_groups(golfer):
        valid = []
        for gi in range(G):
            if len(groups[gi]) < P:
                ok = True
                for member in groups[gi]:
                    if (min(golfer, member), max(golfer, member)) in used_pairs:
                        ok = False
                        break
                if ok:
                    valid.append(gi)
        return valid

    # Backtracking with ordering
    def backtrack(remaining):
        if not remaining:
            return True

        # Choose the golfer with fewest valid groups (MRV)
        best_g = None
        best_valid = None
        best_len = float('inf')

        for g in remaining:
            valid = get_valid_groups(g)
            if len(valid) < best_len:
                best_len = len(valid)
                best_g = g
                best_valid = valid
                if best_len == 0:
                    return False
                if best_len == 1:
                    break

        if best_g is None:
            return False

        new_remaining = [x for x in remaining if x != best_g]

        for gi in best_valid:
            groups[gi].append(best_g)
            if backtrack(new_remaining):
                return True
            groups[gi].pop()

        return False

    if backtrack(list(range(N))):
        return [list(g) for g in groups]
    return None

